import { notFound } from 'next/navigation';
import { ProductDetails } from '@/components/product-details';

interface ProductPageProps {
  params: Promise<{ handle: string }>;
}

async function getProduct(handle: string) {
  const res = await fetch(`https://api.storefront.internal/products/${handle}`, {
    next: { tags: [`product-${handle}`, 'catalog'] },
    headers: {
      'Authorization': `Bearer ${process.env.STOREFRONT_API_TOKEN}`,
      'Content-Type': 'application/json'
    }
  });

  if (!res.ok) return null;
  return res.json();
}

export default async function ProductPage({ params }: ProductPageProps) {
  const { handle } = await params;
  const product = await getProduct(handle);

  if (!product) {
    notFound();
  }

  return (
    <main className="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8">
      <ProductDetails product={product} />
    </main>
  );
}

'use client';

import { useOptimistic, useTransition } from 'react';

export type CartItem = {
  id: string;
  title: string;
  price: number;
  quantity: number;
};

export function useOptimisticCart(initialItems: CartItem[]) {
  const [isPending, startTransition] = useTransition();
  const [optimisticItems, addOptimisticItem] = useOptimistic(
    initialItems,
    (state, newItem: CartItem) => {
      const existingIndex = state.findIndex(item => item.id === newItem.id);
      if (existingIndex > -1) {
        const updated = [...state];
        updated[existingIndex].quantity += newItem.quantity;
        return updated;
      }
      return [...state, newItem];
    }
  );

  async function addItem(product: CartItem) {
    startTransition(async () => {
      addOptimisticItem(product);
      await fetch('/api/cart/add', {
        method: 'POST',
        body: JSON.stringify(product),
        headers: { 'Content-Type': 'application/json' }
      });
    });
  }

  return { cart: optimisticItems, addItem, isPending };
}
